    return json.dumps(data, indent=2)


def _strip_markdown_in_paragraph(text):
    """Parse inline content into a sequence of inline objects."""
    out = []
    i = 0
    # Very simplified: split on image and link patterns, keep other as text
    pattern = re.compile(r'(!\[([^\]]*)\]\(([^)]*)\))|(\[([^\]]*)\]\(([^)]*)\))|(`([^`]*)`)')
    last = 0
    for m in pattern.finditer(text):
        if m.start() > last:
            out.append({"type": "text", "value": text[last:m.start()]})
        if m.group(1):  # image
            out.append({
                "type": "image",
                "alt": m.group(2),
                "src": m.group(3),
                "title": None,
            })
        elif m.group(4):  # link
            out.append({
                "type": "link",
                "text": m.group(5),
                "href": m.group(6),
            })
        elif m.group(7):  # code
            out.append({"type": "code", "value": m.group(8)})
        last = m.end()
    if last < len(text):
        out.append({"type": "text", "value": text[last:]})
    if not out:
        out.append({"type": "text", "value": text})
    return out


def _parse_blocks(content):
    """Very simplified block parser.

    Parses paragraphs, fenced code blocks, lists, blockquotes, and tables.
    """
    blocks = []
    lines = content.split('\n')
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue
        # Fenced code
        m = re.match(r'^(```+|~~~+)\s*(\S*)', line)
        if m:
            fence = m.group(1)[:3]
            lang = m.group(2) or ''
            code_lines = []
            i += 1
            while i < n:
                if lines[i].strip().startswith(fence):
                    i += 1
                    break
                code_lines.append(lines[i])
                i += 1
            blocks.append({
                "type": "code",
                "language": lang,
                "content": '\n'.join(code_lines),
                "start_line": 0,
                "end_line": 0,
            })
            continue
        # List
        if re.match(r'^\s*([-*+]|\d+\.)\s', line):
            items = []
            ordered = bool(re.match(r'^\s*\d+\.\s', line))
            while i < n and re.match(r'^\s*([-*+]|\d+\.)\s', lines[i]):
                item_line = re.sub(r'^\s*([-*+]|\d+\.)\s+', '', lines[i])
                checked = None
                m2 = re.match(r'^\[( |x|X)\]\s+(.*)', item_line)
                if m2:
                    checked = (m2.group(1).lower() == 'x')
                    item_line = m2.group(2)
                items.append({
                    "checked": checked,
                    "content": item_line,
                    "inline": _strip_markdown_in_paragraph(item_line),
                })
                i += 1
            blocks.append({
                "type": "list",
                "ordered": ordered,
                "items": items,
            })
            continue
        # Blockquote
        if line.startswith('>'):
            qlines = []
            while i < n and lines[i].startswith('>'):
                qlines.append(re.sub(r'^>\s?', '', lines[i]))
                i += 1
            blocks.append({
                "type": "blockquote",
                "content": '\n'.join(qlines),
            })
            continue
        # Table: must contain '|' and next line is separator
        if '|' in line and i + 1 < n and re.match(r'^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)+\|?\s*$', lines[i + 1]):
            headers = [c.strip() for c in line.strip().strip('|').split('|')]
            i += 2
            rows = []
            while i < n and '|' in lines[i] and lines[i].strip():
                rows.append([c.strip() for c in lines[i].strip().strip('|').split('|')])
                i += 1
            blocks.append({
                "type": "table",
                "headers": headers,
                "rows": rows,
            })
            continue
        # Paragraph (accumulate consecutive non-blank lines)
        para_lines = [line]
        i += 1
        while i < n and lines[i].strip() and not re.match(r'^(#{1,6})\s', lines[i]):
            para_lines.append(lines[i])
            i += 1
        para = '\n'.join(para_lines)
        blocks.append({
            "type": "paragraph",
            "content": para,
            "inline": _strip_markdown_in_paragraph(para),
        })
    return blocks


def _word_count(text):
    # Count whitespace-separated tokens
    return len(text.split())


def _section_to_json(node, lines, all_headings, sidx_map):
    """Convert a tree node to a section JSON dict."""
    from .parser import slugify
    title = node['title']
    slug = slugify(title)
    start_line = node['line']
    # Find next heading with level <= node.level
    end_line = len(lines)
    for h in all_headings:
        if h['line'] > node['line'] and h['level'] <= node['level']:
            end_line = h['line'] - 1
            break
    # Determine content range: from start_line+1 until next heading (any level)
    content_end = end_line
    for h in all_headings:
        if h['line'] > node['line']:
            content_end = h['line'] - 1
            break
    content_lines = lines[start_line:content_end]
    while content_lines and not content_lines[-1].strip():
        content_lines.pop()
    while content_lines and not content_lines[0].strip():
        content_lines.pop(0)
    raw = '\n'.join(content_lines)
    return {
        "id": slug,
        "level": node['level'],
        "title": title,
        "slug": slug,
        "position": {
            "line": start_line + 1,  # 1-indexed line AFTER heading
            "offset": node['end_offset'],
        },
        "content": {
            "raw": raw,
            "blocks": _parse_blocks(raw),
        },
        "children": [_section_to_json(c, lines, all_headings, sidx_map) for c in node.get('children', [])],
    }


def list_json(text, headings, roots):
    """Full JSON document output for -l -o json."""
    lines = text.split('\n')
    max_depth = max((h['level'] for h in headings), default=0)
    # Word count: count all words in entire document
    # Approximation: count words in all text
    wc = _word_count(text)
    sections = [_section_to_json(r, lines, headings, {}) for r in roots]
    doc = {
        "document": {
            "metadata": {
                "source": None,
                "headingCount": len(headings),
                "maxDepth": max_depth,
                "wordCount": wc,
            },
            "sections": sections,
        }
    }
    return json.dumps(doc, indent=2)
